import React, { useCallback } from 'react';
import Main from '../layouts/Main';
import ProductCard from '../components/ProductCard';
import productsData from '../data/products.json';
import Config from '../utils/config';

const products = productsData.map((product) => ({
  ...product,
  image: `${process.env.PUBLIC_URL}${product.image}`,
}));

const Shop = () => {
  const handleContact = useCallback((product) => {
    // mail to action including the product title
    const subject = 'Product Inquiry';
    const body = `I am interested in the product: ${product.title}`;
    const mailtoLink = `mailto:${Config.contactEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.location.href = mailtoLink;
  }, []);

  return (
    <Main title='Shop' description="Shop page for Ofir Yaron's website.">
      <article className='post' id='shop'>
        <header>
          <div className='title'>
            <h2>Shop</h2>
            <p>Browse my products and contact me for a price offer.</p>
          </div>
        </header>
        <div className='shop-products-grid'>
          {products.map((product) => (
            <ProductCard
              key={product.id}
              title={product.title}
              image={product.image}
              onContact={() => handleContact(product)}
            />
          ))}
        </div>
      </article>
    </Main>
  );
};

export default Shop;
